// Builds the PHESMUN migration scripts from the committed migrations (unchanged, in order):
//   supabase/phesmun/parts/NN-of-MM.sql  — small parts for the Supabase SQL editor (run in order)
// Each part is one transaction. It refuses any database without the PHESMUN target marker, and refuses
// to run unless the ledger holds exactly the migrations of the earlier parts (so order and re-runs are safe).
// It records the original migration versions in supabase_migrations.schema_migrations.
import { readFileSync, readdirSync, writeFileSync, mkdirSync, rmSync } from "node:fs";
import { createHash } from "node:crypto";
const REF = "gglltljhdpkfjnyjmnif";
const MARKER = `conference-os-target=phesmun ref=${REF}`;
const LIMIT = 60_000; // characters per part; large pastes into the SQL editor can be truncated
const dir = new URL("../supabase/migrations/", import.meta.url);
const files = readdirSync(dir).filter(f => /^\d{14}_.+\.sql$/.test(f)).sort();
const migrations = files.map(file => {
  const sql = readFileSync(new URL(file, dir), "utf8");
  const [, version, name] = file.match(/^(\d{14})_(.+)\.sql$/);
  if (sql.includes("$ledger$") || sql.includes("$guard$")) throw Error(`${file} contains a reserved quote tag`);
  return { file, version, name, sql, sha: createHash("sha256").update(sql).digest("hex") };
});
const parts = [];
for (const m of migrations) {
  const last = parts.at(-1);
  if (last && last.reduce((n, x) => n + x.sql.length, 0) + m.sql.length <= LIMIT) last.push(m); else parts.push([m]);
}
const out = new URL("../supabase/phesmun/parts/", import.meta.url);
rmSync(out, { recursive: true, force: true }); mkdirSync(out, { recursive: true });
let done = [];
parts.forEach((part, i) => {
  const label = `${String(i + 1).padStart(2, "0")}-of-${String(parts.length).padStart(2, "0")}`;
  const expected = done.map(m => `'${m.version}'`).join(",");
  const lines = [
    `-- PHESMUN OS migrations, part ${i + 1} of ${parts.length}: ${part.map(m => m.version).join(", ")}`,
    `-- Target: Supabase project ${REF} (PHESMUN - Production) ONLY. Run parts in order, each exactly once.`,
    `-- Generated by scripts/build-phesmun-migration-bundle.mjs from the committed migrations; do not edit by hand.`,
    `-- One transaction: on any error nothing in this part is applied.`,
    `begin;`,
    `do $guard$ begin`,
    ` if to_regnamespace('supabase_migrations') is null or coalesce(obj_description('supabase_migrations'::regnamespace,'pg_namespace'),'') <> '${MARKER}' then`,
    `  raise exception 'Target guard: this is not the PHESMUN database (${REF}). Nothing was applied.'; end if;`,
    ` if coalesce((select array_agg(version order by version) from supabase_migrations.schema_migrations),'{}'::text[]) <> ${expected ? `array[${expected}]::text[]` : `'{}'::text[]`} then`,
    `  raise exception 'Order guard: run part ${label} only after part${i ? `s 1-${i}` : ""}${i ? "" : "s: none (this is the first part) on an empty ledger"}, and only once. Nothing was applied.'; end if;`,
    `end $guard$;`,
  ];
  for (const m of part) lines.push(``, `-- ===== ${m.file} (sha256 ${m.sha}) =====`, m.sql.trimEnd(),
    `insert into supabase_migrations.schema_migrations(version,name,statements) values('${m.version}','${m.name}',array[$ledger$-- applied from supabase/migrations/${m.file} (sha256 ${m.sha})$ledger$]);`);
  done = [...done, ...part];
  lines.push(``, `commit;`, `select '${label} applied' as part, count(*) as migrations_in_ledger, ${done.length} as expected from supabase_migrations.schema_migrations;`, ``);
  writeFileSync(new URL(`${label}.sql`, out), lines.join("\n"));
  console.log(label, part.map(m => m.version).join(" "), lines.join("\n").length);
});
